    vector<int> favorite(N), disliked(N);

    for (int i = 0; i < N; ++i) {
        cin >> favorite[i] >> disliked[i];
        if (firstHater[disliked[i]] == -1)
            firstHater[disliked[i]] = i;
    }

    vector<bool> visited(M + 1, false);
    long long swaps = 0;
    int song = C;

    while (firstHater[song] != -1) {
        if (visited[song]) {
